import redis, sys, json

def canon(r, db, k):
    t = r.type(k).decode()
    if t == 'string':
        v = r.get(k)
        return ('string', v)
    if t == 'list':
        return ('list', r.lrange(k,0,-1))
    if t == 'set':
        return ('set', sorted(r.smembers(k)))
    if t == 'hash':
        return ('hash', sorted(r.hgetall(k).items()))
    if t == 'zset':
        return ('zset', r.zrange(k,0,-1,withscores=True))
    if t == 'stream':
        entries = r.xrange(k)
        try:
            groups = r.xinfo_groups(k)
        except Exception as e:
            groups = [('err',str(e))]
        gdata=[]
        for g in groups:
            gname = g['name']
            gd = {'name':gname,
                  'last_delivered':g['last-delivered-id'],
                  'entries_read':g.get('entries-read'),
                  'lag':g.get('lag'),
                  'consumers':[],
                  'pending':[]}
            try:
                for c in r.xinfo_consumers(k, gname):
                    gd['consumers'].append((c['name'], c['pending'], c.get('inactive')))
            except Exception as e:
                gd['consumers'].append(('err',str(e)))
            try:
                for p in r.xpending_range(k, gname, min='-', max='+', count=100000):
                    gd['pending'].append((p['message_id'], p['consumer'], p['time_since_delivered'], p['times_delivered']))
            except Exception as e:
                gd['pending'].append(('err',str(e)))
            gd['pending'].sort()
            gd['consumers'].sort()
            gdata.append(gd)
        gdata.sort(key=lambda x:x['name'])
        return ('stream', entries, gdata)
    return (t, None)

def main():
    a = redis.Redis(port=6379)
    b = redis.Redis(port=6380)
    problems=[]
    total=0
    for db in range(16):
        ra = redis.Redis(port=6379, db=db)
        rb = redis.Redis(port=6380, db=db)
        ka = sorted(ra.keys('*'))
        kb = sorted(rb.keys('*'))
        if ka != kb:
            problems.append(f"DB{db} keyset differs: master={len(ka)} replica={len(kb)}")
            only_a = set(ka)-set(kb); only_b=set(kb)-set(ka)
            if only_a: problems.append(f"  only on master ({len(only_a)}): {list(only_a)[:10]}")
            if only_b: problems.append(f"  only on replica ({len(only_b)}): {list(only_b)[:10]}")
        for k in ka:
            total+=1
            if k not in kb: 
                continue
            ta = ra.type(k); tb = rb.type(k)
            if ta!=tb:
                problems.append(f"DB{db} {k}: type {ta} != {tb}"); continue
            ca = canon(ra,db,k); cb = canon(rb,db,k)
            if ca!=cb:
                # allow pending times_since_delivered differences for streams
                if ca[0]=='stream' and cb[0]=='stream':
                    if ca[1]==cb[1] and json.dumps([[g['name'],g['last_delivered'],g['entries_read'],g['lag'],g['consumers'],[(p[0],p[1],p[3]) for p in g['pending']]] for g in ca[2]]) == json.dumps([[g['name'],g['last_delivered'],g['entries_read'],g['lag'],g['consumers'],[(p[0],p[1],p[3]) for p in g['pending']]] for g in cb[2]]):
                        pass
                    else:
                        problems.append(f"DB{db} {k}: stream content differs (see below)")
                        problems.append("  MASTER: "+json.dumps([[g['name'],g['last_delivered'],g['entries_read'],g['lag'],g['consumers'],g['pending']] for g in ca[2]],default=str)[:800])
                        problems.append("  REPL  : "+json.dumps([[g['name'],g['last_delivered'],g['entries_read'],g['lag'],g['consumers'],g['pending']] for g in cb[2]],default=str)[:800])
                else:
                    problems.append(f"DB{db} {k}: value differs; master={str(ca)[:200]} replica={str(cb)[:200]}")
            # TTL
            tta = ra.ttl(k); ttb = rb.ttl(k)
            if abs(tta-ttb) > 2:
                problems.append(f"DB{db} {k}: TTL differs master={tta} replica={ttb}")
    print(f"Checked {total} keys")
    if problems:
        print(f"\n!!! {len(problems)} PROBLEMS:")
        for p in problems[:80]: print(p)
        sys.exit(1)
    else:
        print("ALL MATCH (types, values, ttls, stream groups)")

main()
